mapper.select:
SELECT E.SUBJECT_ID, E.SUBJECT_NO, E.SUBJECT_NAME, E.MAIN_BUSINESS, E.MAIN_BUSINESS_NAME FROM EDU_TRAIN_SUBJECT E WHERE E.ACTIVITY = '1' AND E.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND UPPER(E.SUBJECT_NAME) LIKE '%' || UPPER(#{subjectName, jdbcType=VARCHAR}) || '%'
AND E.SUBJECT_NO = #{subjectNo, jdbcType=VARCHAR}
AND E.MAIN_BUSINESS LIKE '%' || #{mainBusiness, jdbcType=VARCHAR} || '%'
ORDER BY E.SUBJECT_NO ASC

SELECT E.SUBJECT_ID, E.SUBJECT_NO, E.SUBJECT_NAME, E.MAIN_BUSINESS, E.MAIN_BUSINESS_NAME
FROM EDU_TRAIN_SUBJECT E
WHERE E.SUBJECT_ID = #{subjectId, jdbcType=VARCHAR}
  AND E.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND E.ACTIVITY <> '0'

SELECT COUNT(1)
FROM EDU_TRAIN_SUBJECT E
WHERE E.ACTIVITY = '1'
  AND E.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND E.SUBJECT_NO = #{subjectNo, jdbcType=VARCHAR}

    AND E.SUBJECT_ID <> #{excludeId, jdbcType=VARCHAR}

mapper.update:
UPDATE EDU_TRAIN_SUBJECT
   SET SUBJECT_NO = #{subjectNo, jdbcType=VARCHAR},
       SUBJECT_NAME = #{subjectName, jdbcType=VARCHAR},
       MAIN_BUSINESS = #{mainBusiness, jdbcType=VARCHAR},
       MAIN_BUSINESS_NAME = #{mainBusinessName, jdbcType=VARCHAR},
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP = #{adminIP, jdbcType=VARCHAR}
 WHERE SUBJECT_ID = #{subjectId, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

UPDATE EDU_TRAIN_SUBJECT
   SET ACTIVITY = '0'
 WHERE SUBJECT_ID = #{subjectId, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
